<?php
/**
 * graphic_pain_map/new.php
 *
 * Renders the interactive pain map form and handles AJAX save POSTs.
 *
 * FIXES vs. the original broken version:
 *   1. Removed f_name/l_name GET lookup — $pid/$encounter already exist in
 *      OpenEMR globals (set by the session before this file is included).
 *   2. Removed sqlStatement() + sqlBindParam() + sqlExecute() pattern —
 *      that is NOT how OpenEMR's DB API works. Replaced with the correct
 *      sqlStatement($query, $paramsArray) and sqlInsert($query, $paramsArray).
 *   3. Fixed broken fetch() — the .then()/.catch()/.finally() chains were
 *      placed OUTSIDE the closing brace of savePainMap(), making them
 *      top-level syntax errors. They are now inside the function.
 *   4. Schema aligned to our actual form_painmap table columns
 *      (markers_json, marker_count, max_pain, regions_text, provider_notes).
 *      The original referenced non-existent columns (encounter_id, data, activity as text).
 *   5. Added CSRF token (collected in PHP, sent as X-CSRF-Token header in JS).
 *   6. addForm() called on INSERT so the form appears in the encounter sidebar.
 *   7. On a successful INSERT the server returns the new formid; JS stores it
 *      so the next Save becomes an UPDATE instead of a duplicate INSERT.
 *
 * @package   OpenEMR
 * @link      http://www.open-emr.org
 * @license   https://github.com/openemr/openemr/blob/master/LICENSE GNU General Public License 3
 */

 ob_start(); // Must be FIRST — catches any error output from includes

 require_once(__DIR__ . '/../../globals.php');
require_once("$srcdir/api.inc.php");
require_once("$srcdir/forms.inc.php");

 
 use OpenEMR\Common\Acl\AclMain;
 use OpenEMR\Common\Csrf\CsrfUtils;

// ── ACL ────────────────────────────────────────────────────────────────────
if (!AclMain::aclCheckCore('encounters', 'notes')) {
    if (!empty($_SERVER['HTTP_X_REQUESTED_WITH'])) {
        header('Content-Type: application/json');
        echo json_encode(['success' => false, 'message' => 'Access not authorized.']);
    } else {
        die(xlt('Access Not Authorized'));
    }
    exit;
}

// ── $pid and $encounter are injected by OpenEMR's globals.php ──────────────
// DO NOT query them from GET params or from patient_data by name.
$pid       = (int)($pid       ?? $_SESSION['pid']       ?? 0);
$encounter = (int)($encounter ?? $_SESSION['encounter'] ?? 0);

// Existing record id when re-opening a saved form for editing
$formid = (int)($_GET['id'] ?? 0);

// ════════════════════════════════════════════════════════════════════════════
//  AJAX POST — save/update, return JSON
// ════════════════════════════════════════════════════════════════════════════
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  ob_end_clean(); // discard anything printed during includes
  header('Content-Type: application/json');
  set_exception_handler(function($e) {
      echo json_encode(['success' => false, 'message' => $e->getMessage()]);
      exit;
  });

    // CSRF — JS sends the token as the X-CSRF-Token request header
    $token = $_SERVER['HTTP_X_CSRF_TOKEN'] ?? $_POST['csrf_token_form'] ?? '';
    if (!CsrfUtils::verifyCsrfToken($token)) {
        echo json_encode(['success' => false, 'message' => 'CSRF token invalid.']);
        exit;
    }

$formidPost    = (int)($_POST['formid']  ?? 0);
$providerNotes = substr($_POST['provider_notes'] ?? '', 0, 5000);
$dots          = json_decode($_POST['dots']       ?? '[]', true) ?: [];
$painScores    = json_decode($_POST['painScores'] ?? '[]', true) ?: [];
$markerNotes   = json_decode($_POST['notes']      ?? '[]', true) ?: [];

$markerCount = count($dots);
$scoreValues = array_values($painScores);
$maxPain     = count($scoreValues) ? (int)max($scoreValues) : null;
$regions     = implode(', ', array_unique(array_column($dots, 'region')));

$markersJson = base64_encode(json_encode([
  'dots'       => $dots,
  'painScores' => $painScores,
  'notes'      => $markerNotes,
]));

if (!empty($row['markers_json'])) {
  $decoded = base64_decode($row['markers_json']);
  $savedMarkers = $decoded ?: 'null';
}



    // Derived summary columns (stored denormalized for quick report queries)
    $markerCount = count($dots);
    $scoreValues = array_values($painScores);
    $maxPain     = count($scoreValues) ? (int)max($scoreValues) : null;
    $regions     = implode(', ', array_unique(array_column($dots, 'region')));

    $markersJson = json_encode([
      'dots'       => $dots,
      'painScores' => $painScores,
      'notes'      => $markerNotes,
  ]);

    if ($formidPost) {
        // ── UPDATE existing record ──────────────────────────────────────────
        // sqlStatement(query, params_array) — no bind/execute steps needed
        sqlStatement(
            "UPDATE form_painmap
             SET date           = NOW(),
                 markers_json   = ?,
                 marker_count   = ?,
                 max_pain       = ?,
                 regions_text   = ?,
                 provider_notes = ?
             WHERE id = ? AND pid = ?",
            [$markersJson, $markerCount, $maxPain, $regions, $providerNotes,
             $formidPost, $pid]
        );
        echo json_encode(['success' => true, 'formid' => $formidPost, 'message' => 'Pain map updated.']);

    } else {
        // ── INSERT new record ───────────────────────────────────────────────
        // sqlInsert() returns the new auto-increment id
        $newId = sqlInsert(
            "INSERT INTO form_painmap
                (date, pid, encounter, user, groupname, authorized, activity,
                 markers_json, marker_count, max_pain, regions_text, provider_notes)
             VALUES (NOW(), ?, ?, ?, ?, ?, 1, ?, ?, ?, ?, ?)",
            [
                $pid,
                $encounter,
                $_SESSION['authUser']     ?? '',
                $_SESSION['authProvider'] ?? 'Default',
                $userauthorized           ?? 0,
                $markersJson,
                $markerCount,
                $maxPain,
                $regions,
                $providerNotes,
            ]
        );

        if ($newId) {
            // Register in encounter forms list so it shows up in the sidebar
            // and report.php gets called for the collapsible summary row.
            addForm($encounter, 'Graphic Pain Map', $newId, 'pain_map', $pid, $userauthorized ?? 0);
            echo json_encode(['success' => true, 'formid' => $newId, 'message' => 'Pain map saved.']);
        } else {
            echo json_encode(['success' => false, 'message' => 'Database insert failed.']);
        }
    }
    exit;
}

// ════════════════════════════════════════════════════════════════════════════
//  GET — load existing data if editing, then fall through to render HTML
// ════════════════════════════════════════════════════════════════════════════
$savedMarkers = 'null'; // will be inlined into JS
$savedNotes   = '';

if ($formid) {
  $row = sqlQuery(
      "SELECT * FROM form_painmap WHERE id = ? AND pid = ? AND activity = 1",
      [$formid, $pid]
  );
  if (!empty($row['markers_json'])) {
      // Data is stored as base64 — decode it back to JSON for the JS
      $decoded = base64_decode($row['markers_json']);
      if ($decoded !== false && json_decode($decoded) !== null) {
          $savedMarkers = $decoded;
      } else {
          // Fallback: already raw JSON (old records before base64 change)
          $savedMarkers = $row['markers_json'];
      }
  }
  if (!empty($row['provider_notes'])) {
      $savedNotes = htmlspecialchars($row['provider_notes'], ENT_QUOTES, 'UTF-8');
  }
}

// GET path — clean buffer then render
ob_end_clean();
$csrfToken = CsrfUtils::collectCsrfToken();
?>
