<div id="toast"></div>

<script>
// ── PHP → JS ──────────────────────────────────────────────────
// CSRF token is sent as X-CSRF-Token on every fetch() POST.
// currentFormId is 0 on a new form; after the first save the
// server echoes back the new id so subsequent saves UPDATE.
const CSRF_TOKEN    = <?php echo js_escape($csrfToken); ?>;
const SAVE_URL = '<?php echo $web_root; ?>/interface/forms/painmap/save.php';
let   currentFormId = <?php echo (int)$formid; ?>;

// ── State ─────────────────────────────────────────────────────
let dots = [], dotId = 0, selId = null, history = [], notes = {}, painScores = {}, panelOpen = true;


// ── Region Mode ─────────────────────────────────────────────────────
let regionMode = true;

const regionBtn =
    document.getElementById('btn-region-mode');

regionBtn.addEventListener('click', function() {

    regionMode = !regionMode;

    this.textContent =
        regionMode
        ? 'Region Mode: ON'
        : 'Region Mode: OFF';

    showToast(
        regionMode
        ? 'Free-click disabled'
        : 'Free-click enabled'
    );

});

document
.getElementById('showRegions')
.addEventListener('change',function(){

    document.body.classList.toggle(
        'show-regions',
        this.checked
    );

});

// ── Restore saved data (edit mode) ───────────────────────────
(function loadSaved() {
    const saved = <?php echo $savedMarkers; ?>;
    if (!saved || !saved.dots) return;
    saved.dots.forEach(d => {
        if (d.id >= dotId) dotId = d.id;
        dots.push(d); renderDot(d); buildLogEntry(d);
    });
    if (saved.painScores) Object.assign(painScores, saved.painScores);
    if (saved.notes)      Object.assign(notes,      saved.notes);
    Object.entries(painScores).forEach(([id, score]) => updateLogPainBadge(parseInt(id), score));
    Object.keys(notes).forEach(id => { const ni = document.getElementById('ni-'+id); if (ni && notes[id]) ni.style.display=''; });
    updateCount();
})();

// ── Pain metadata ─────────────────────────────────────────────
const painDesc = {
    0:'No Pain',1:'Minimal',2:'Very Mild',3:'Mild',4:'Mild–Moderate',
    5:'Moderate',6:'Moderate–Severe',7:'Severe',8:'Very Severe',9:'Excruciating',10:'Worst Possible'
};
const painColor = {
    0:'#22c55e',1:'#4ade80',2:'#86efac',3:'#fde68a',4:'#fcd34d',
    5:'#fbbf24',6:'#fb923c',7:'#f97316',8:'#ef4444',9:'#dc2626',10:'#b91c1c'
};

// ── Build pip track ───────────────────────────────────────────
(function buildPips() {
    const c = document.getElementById('ps-pips');
    for (let i = 0; i <= 10; i++) {
        const p = document.createElement('div');
        p.className = 'ps-pip'; p.id = 'pip-'+i;
        p.innerHTML = `<div class="ps-pip-dot"></div><span>${i}</span>`;
        p.onclick = () => { if (selId !== null) { document.getElementById('ps-slider').value=i; onScaleInput(i); } };
        c.appendChild(p);
    }
})();

function onScaleInput(v) {
    v = parseInt(v);
    document.getElementById('ps-num').textContent = v;
    document.getElementById('ps-num').style.color  = painColor[v];
    document.getElementById('ps-desc').textContent = painDesc[v];
    document.querySelectorAll('.ps-pip').forEach((p,i) => p.classList.toggle('active', i===v));
    if (selId !== null) { painScores[selId]=v; updateLogPainBadge(selId,v); }
}
function updateLogPainBadge(id, score) {
    const el = document.getElementById('log-pain-'+id); if (!el) return;
    el.textContent = 'Pain: '+score+'/10 · '+painDesc[score]; el.style.display='';
}
function openScaleForDot(id) {
    const dot = dots.find(d=>d.id===id); if (!dot) return;
    const score = painScores[id] !== undefined ? painScores[id] : 5;
    document.getElementById('ps-panel').classList.remove('disabled');
    const badge = document.getElementById('ps-badge'); badge.textContent=dot.region; badge.classList.remove('hidden');
    const sl = document.getElementById('ps-slider'); sl.disabled=false; sl.value=score;
    document.getElementById('ps-num').textContent=score; document.getElementById('ps-num').style.color=painColor[score];
    document.getElementById('ps-num').className='ps-num'; document.getElementById('ps-desc').textContent=painDesc[score];
    document.querySelectorAll('.ps-pip').forEach((p,i) => p.classList.toggle('active', i===score));
}
function resetScale() {
    document.getElementById('ps-panel').classList.add('disabled');
    document.getElementById('ps-badge').classList.add('hidden');
    const sl=document.getElementById('ps-slider'); sl.disabled=true; sl.value=5;
    document.getElementById('ps-num').textContent='—'; document.getElementById('ps-num').className='ps-num disabled';
    document.getElementById('ps-num').style.color=''; document.getElementById('ps-desc').textContent='Select a marker to rate pain';
    document.querySelectorAll('.ps-pip').forEach(p=>p.classList.remove('active'));
}

// ── Region hit-testing ────────────────────────────────────────
const regionMap = {
     front:[

    {n:'Head',x:[44,56],y:[3,13]},

    {n:'Cervical Spine (C1–7)',x:[47,54],y:[13,22]},

    {n:'Left Shoulder',x:[35,43],y:[17,25]},
    {n:'Right Shoulder',x:[57,65],y:[17,25]},

    {n:'Left Pectoralis',x:[40,50],y:[25,35]},
    {n:'Right Pectoralis',x:[50,60],y:[25,35]},

    {n:'Upper Abdomen',x:[44,56],y:[31,39]},
    {n:'Lower Abdomen',x:[44,56],y:[37,45]},

    {n:'Left Upper Arm',x:[34,40],y:[25,39]},
    {n:'Right Upper Arm',x:[60,66],y:[25,39]},

    {n:'Left Forearm',x:[29,35],y:[40,54]},
    {n:'Right Forearm',x:[65,71],y:[40,54]},

    {n:'Left Hand',x:[28,34],y:[52,58]},
    {n:'Right Hand',x:[66,72],y:[52,58]},

    {n:'Left Hip',x:[41,49],y:[55,63]},
    {n:'Right Hip',x:[51,59],y:[55,63]},

    {n:'Left Thigh',x:[41,49],y:[64,75]},
    {n:'Right Thigh',x:[54,61],y:[64,75]},

    {n:'Left Knee',x:[40,48],y:[73,79]},
    {n:'Right Knee',x:[53,61],y:[73,79]},

    {n:'Left Shin',x:[41,49],y:[84,97]},
    {n:'Right Shin',x:[51,59],y:[84,97]}
    ],
    back:[

    {n:'Skull / Occiput',x:[43,57],y:[2,12]},

    {n:'Cervical Spine (C1–7)',x:[47,54],y:[13,22]},

    {n:'Left Trapezius',x:[31,47],y:[18,28]},
    {n:'Right Trapezius',x:[53,69],y:[18,28]},

    {n:'Left Scapula',x:[30,45],y:[25,37]},
    {n:'Right Scapula',x:[55,70],y:[25,37]},

    {n:'Thoracic Spine (T1–T12)',x:[47,54],y:[22,37]},
    {n:'Lumbar Spine (L1–5)',x:[47,54],y:[36,45]},

    {n:'Left Lumbar Paraspinal',x:[39,47],y:[34,47]},
    {n:'Right Lumbar Paraspinal',x:[53,61],y:[34,47]},

    {n:'Left SI Joint',x:[42,48],y:[49,55]},
    {n:'Right SI Joint',x:[52,58],y:[49,55]},

    {n:'Sacrum / Coccyx',x:[47,54],y:[45,55]},

    {n:'Left Gluteus',x:[39,49],y:[53,62]},
    {n:'Right Gluteus',x:[51,61],y:[53,62]},

    {n:'Left Hamstring',x:[41,49],y:[63,78]},
    {n:'Right Hamstring',x:[51,59],y:[63,78]},

    {n:'Left Calf',x:[41,49],y:[84,98]},
    {n:'Right Calf',x:[51,59],y:[84,98]}
    ]
};
function getRegion(view,x,y) {
    for (const r of (regionMap[view]||regionMap.front)) { if (x>=r.x[0]&&x<=r.x[1]&&y>=r.y[0]&&y<=r.y[1]) return r.n; }
    return 'Body';
}


// ── Dot placement ─────────────────────────────────────────────
function addDot(e, view) {

if (regionMode) {
    return;
}

const img=e.currentTarget, rect=img.getBoundingClientRect();
const xPct=(e.clientX-rect.left)/rect.width*100;
const yPct=(e.clientY-rect.top)/rect.height*100;

place(
    getRegion(view, xPct, yPct),
    view,
    xPct,
    yPct
);
}
function qm(region, view, x, y) {
    const front=document.getElementById('fig-front'), back=document.getElementById('fig-back');
    if (view==='front'&&front.style.display==='none') {
        back.style.display='none'; front.style.display='';
        document.querySelectorAll('.view-btn').forEach((b,i)=>b.classList.toggle('active',i===0));
    } else if (view==='back'&&back.style.display==='none') {
        front.style.display='none'; back.style.display='';
        document.querySelectorAll('.view-btn').forEach((b,i)=>b.classList.toggle('active',i===1));
    }
    place(region, view, x, y);
}
function place(region, view, x, y) {
    const id=++dotId, dot={id,view,x,y,region};
    dots.push(dot); history.push(id); renderDot(dot); buildLogEntry(dot); updateCount(); selectDot(id);
    showToast('Marked: '+region);
}
function renderDot(dot) {
    const overlay=document.getElementById('dots-'+dot.view); if (!overlay) return;
    const img=overlay.previousElementSibling;
    // Get img position relative to the overlay's offsetParent (the wrapper div)
    // Using offsetLeft/offsetTop avoids scroll-dependent getBoundingClientRect
    const imgLeft=img.offsetLeft, imgTop=img.offsetTop;
    const imgW=img.offsetWidth, imgH=img.offsetHeight;
    const ovW=overlay.offsetWidth, ovH=overlay.offsetHeight;
    // Convert dot percentages (relative to img) to pixels relative to overlay
    const px = imgLeft + dot.x/100 * imgW;
    const py = imgTop  + dot.y/100 * imgH;
    const el=document.createElement('div');
    el.className='pain-dot pi'; el.id='dot-'+dot.id;
    el.style.cssText=`left:${px}px;top:${py}px;pointer-events:all`;
    el.innerHTML=`<div class="dot-tip">${dot.region}</div>`;
    el.onclick=ev=>{ev.stopPropagation();selectDot(dot.id);};
    overlay.appendChild(el);
}

// ── Selection ─────────────────────────────────────────────────
function selectDot(id) {
    if (selId!==null) {
        document.getElementById('dot-'+selId)?.classList.remove('sel');
        document.getElementById('log-'+selId)?.classList.remove('sel-e');
    }
    selId=id;
    document.getElementById('dot-'+id)?.classList.add('sel');
    const nl=document.getElementById('log-'+id);
    if (nl){nl.classList.add('sel-e');nl.scrollIntoView({behavior:'smooth',block:'nearest'});}
    openScaleForDot(id); openNotePanel(id);
}

// ── Note panel ────────────────────────────────────────────────
function openNotePanel(id) {
    const dot=dots.find(d=>d.id===id); if (!dot) return;
    document.getElementById('np-title').textContent='Notes';
    document.getElementById('np-title').className='np-title active';
    const badge=document.getElementById('np-badge'); badge.textContent=dot.region; badge.style.display='';
    document.getElementById('note-hint').style.display='none';
    const ta=document.getElementById('note-ta'); ta.style.display=''; ta.disabled=false; ta.value=notes[id]||'';
    document.getElementById('note-foot').style.display=''; updateNoteChars(); if (!panelOpen) toggleNotePanel(); ta.focus();
}
function buildLogEntry(dot) {
    document.getElementById('log-empty').style.display='none';
    const list=document.getElementById('log-list');
    const e=document.createElement('div'); e.className='log-entry'; e.id='log-'+dot.id;
    e.onclick=()=>selectDot(dot.id);
    e.innerHTML=`
        <div class="log-num">${dot.id}</div>
        <div class="log-info">
            <div class="log-region">${dot.region}</div>
            <div class="log-has-note" id="log-pain-${dot.id}" style="display:none;color:var(--muted)"></div>
            <div class="log-has-note" id="ni-${dot.id}" style="display:none">
                <svg width="9" height="9" fill="none" stroke="currentColor" stroke-width="2.5" viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>Has note
            </div>
        </div>
        <div style="display:flex;gap:3px">
            <div class="leb" title="Edit note" onclick="event.stopPropagation();selectDot(${dot.id})">
                <svg width="11" height="11" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>
            </div>
            <div class="leb del" title="Delete" onclick="event.stopPropagation();removeDot(${dot.id})">
                <svg width="11" height="11" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg>
            </div>
        </div>`;
    list.appendChild(e);
}
function onNoteInput()     { updateNoteChars(); autoSaveNote(); }
function updateNoteChars() { document.getElementById('note-chars').textContent=document.getElementById('note-ta').value.length+' / 500'; }
function autoSaveNote() {
    if (selId===null) return;
    const val=document.getElementById('note-ta').value; notes[selId]=val;
    const ni=document.getElementById('ni-'+selId); if (ni) ni.style.display=val.trim()?'':'none';
}
function saveNote() {
    if (selId===null) return;
    const val=document.getElementById('note-ta').value.trim(); notes[selId]=val;
    const ni=document.getElementById('ni-'+selId); if (ni) ni.style.display=val?'':'none';
}
function removeDot(id) {
    dots=dots.filter(d=>d.id!==id); delete notes[id]; delete painScores[id]; history=history.filter(h=>h!==id);
    const de=document.getElementById('dot-'+id);
    if (de){de.style.cssText+=';transform:translate(-50%,-50%) scale(0);opacity:0;transition:all .18s';setTimeout(()=>de.remove(),200);}
    const le=document.getElementById('log-'+id);
    if (le){le.style.cssText+=';opacity:0;transform:translateX(10px);transition:all .18s';setTimeout(()=>le.remove(),200);}
    if (selId===id){selId=null;resetNote();resetScale();}
    updateCount(); showToast('Marker removed');
}
function resetNote() {
    document.getElementById('np-title').textContent='Marker Notes'; document.getElementById('np-title').className='np-title';
    document.getElementById('np-badge').style.display='none'; document.getElementById('note-hint').style.display='';
    document.getElementById('note-ta').style.display='none'; document.getElementById('note-foot').style.display='none';
}
function updateCount() {
    const n=dots.length;
    document.getElementById('dot-count').textContent=n+' marker'+(n!==1?'s':'');
    document.getElementById('log-count').textContent=n;
    if (!n){document.getElementById('log-empty').style.display='';resetNote();resetScale();}
}
function undoLast() { if (!history.length){showToast('Nothing to undo');return;} removeDot(history[history.length-1]); }
function clearAll() { if (!dots.length){showToast('No markers');return;} if (!confirm('Clear all markers and notes?')) return; [...dots].map(d=>d.id).forEach(removeDot); history=[]; }
function setView(v,btn) {
    document.querySelectorAll('.view-btn').forEach(b=>b.classList.remove('active')); btn.classList.add('active');
    document.getElementById('fig-front').style.display=(v==='front'||v==='both')?'':'none';
    document.getElementById('fig-back').style.display=(v==='back'||v==='both')?'':'none';
}
function toggleNotePanel() {
    panelOpen=!panelOpen;
    document.getElementById('note-panel').className='note-panel '+(panelOpen?'expanded':'collapsed');
}

// ── AJAX save ─────────────────────────────────────────────────
// FIX: btn is passed explicitly as a parameter — no event.target needed.
// FIX: .then()/.catch()/.finally() are INSIDE the function (original had
//      them outside the closing brace, which is a syntax error).
function savePainMap(btn) {
    if (selId !== null) saveNote(); // flush current textarea

    const orig = btn.innerHTML;
    btn.innerHTML = `<svg width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" style="animation:spin .7s linear infinite"><path d="M21 12a9 9 0 1 1-6.22-8.56"/></svg> Saving…`;
    btn.disabled = true;

    fetch(SAVE_URL, {
    method: 'POST',
    headers: {
        'X-CSRF-Token':     CSRF_TOKEN,
        'X-Requested-With': 'XMLHttpRequest',
    },
    body: new URLSearchParams({
        csrf_token_form: CSRF_TOKEN,
        formid:          currentFormId,
        dots:            JSON.stringify(dots),
        painScores:      JSON.stringify(painScores),
        notes:           JSON.stringify(notes),
        provider_notes:  '',
    }),
})
.then(r => {
    if (!r.ok) throw new Error('HTTP ' + r.status);
    return r.text(); // get raw text first
})
.then(raw => {
    // Show raw response if not valid JSON
    let data;
    try {
        data = JSON.parse(raw);
    } catch(e) {
        showToast('Save error — raw: ' + raw.substring(0, 120));
        console.error('Non-JSON response:', raw);
        return;
    }
    if (data.success) {
        currentFormId = data.formid;
        showToast('✓ Pain map saved');
    } else {
        showToast('Error: ' + (data.message || 'Unknown error'));
    }
})
.catch(err => {
    console.error('Save error:', err);
    showToast('Error: ' + err.message);
})
.finally(() => {
    btn.innerHTML = orig;
    btn.disabled  = false;
});
}

// ── Toast ─────────────────────────────────────────────────────
function showToast(msg) {
    const t=document.getElementById('toast');
    t.innerHTML=`<svg width="12" height="12" fill="none" stroke="#a78bfa" stroke-width="2.5" viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg> ${msg}`;
    t.style.opacity='1'; t.style.transform='translateX(-50%) translateY(0)'; t.style.pointerEvents='auto';
    clearTimeout(t._t);
    t._t=setTimeout(()=>{t.style.opacity='0';t.style.transform='translateX(-50%) translateY(20px)';t.style.pointerEvents='none';},2400);
}

// ── Build Regions ─────────────────────────────────────────────
function buildRegionOverlays()
{
    document
      .querySelectorAll('.region-hitbox')
      .forEach(e=>e.remove());

    ['front','back'].forEach(view=>{

        const overlay =
            document.getElementById(
                view+'-overlay'
            );

        if(!overlay) return;

        regionMap[view].forEach(region=>{

            const box =
                document.createElement('div');

            box.className='region-hitbox';

            box.style.left =
                region.x[0]+'%';

            box.style.top =
                region.y[0]+'%';

            box.style.width =
                (region.x[1]-region.x[0])+'%';

            box.style.height =
                (region.y[1]-region.y[0])+'%';

            box.dataset.region =
                region.n;

            box.dataset.view =
                view;

            overlay.appendChild(box);

        });

    });

}

document.addEventListener('click',function(e){

const box =
    e.target.closest('.region-hitbox');

if(!box) return;

if(!regionMode) return;

const region =
    box.dataset.region;

const view =
    box.dataset.view;

const hit =
    regionMap[view]
        .find(r=>r.n===region);

const x =
    (hit.x[0]+hit.x[1])/2;

const y =
    (hit.y[0]+hit.y[1])/2;

place(
    region,
    view,
    x,
    y
);

});
document.addEventListener('DOMContentLoaded', function(){

buildRegionOverlays();

});
</script>
</body>
</html>